from itertools import product

dice = [[] for _ in range(5)]

for p in product(range(12), repeat=30):
    for i in range(5):
        dice[i] = sorted([p[i*6+j] for j in range(6)])

    satisfied = True
    for i in range(5):
        count = 0
        for a in dice[i]:
            for b in dice[(i+1)%5]:
                if a > b:
                    count += 1
        if count <= 18:
            satisfied = False
            break

    if satisfied:
        print([x for die in dice for x in die])
        break
else:
    print("UNSATISFIABLE")
